import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.BS0bAV7E.js";const h=JSON.parse('{"title":"Filesystems and storage","description":"","frontmatter":{},"headers":[],"relativePath":"manual/filesystems.md","filePath":"manual/filesystems.md"}'),o={name:"manual/filesystems.md"};function i(l,e,d,r,c,p){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="filesystems-and-storage" tabindex="-1">Filesystems and storage <a class="header-anchor" href="#filesystems-and-storage" aria-label="Permalink to &quot;Filesystems and storage&quot;">​</a></h1><h2 id="the-vfs" tabindex="-1">The VFS <a class="header-anchor" href="#the-vfs" aria-label="Permalink to &quot;The VFS&quot;">​</a></h2><p>All file access goes through one VFS (<code>fs/fs_vfs.c</code>): a uniform open/read/write/seek/close/stat/mkdir/rmdir/readdir/lookup API over pluggable filesystem types. Paths walk the global node tree and cross mount points transparently. Per-filesystem case sensitivity, enforced permission bits, and 64-bit seek offsets are real VFS behaviours.</p><h2 id="filesystem-types" tabindex="-1">Filesystem types <a class="header-anchor" href="#filesystem-types" aria-label="Permalink to &quot;Filesystem types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Read</th><th>Write</th><th>Where it lives</th></tr></thead><tbody><tr><td>ramfs</td><td>yes</td><td>yes</td><td>memory (volatile) - the default root</td></tr><tr><td>FAT32</td><td>yes</td><td>yes</td><td>any block device; LFN supported</td></tr><tr><td>exFAT</td><td>yes</td><td>yes</td><td>any block device</td></tr><tr><td>ext4</td><td>yes</td><td>yes</td><td>any block device (extent-based)</td></tr><tr><td>/etc volume</td><td>yes</td><td>yes</td><td>a small FAT32 image mounted at /etc</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dskstat                     (list block devices)</span></span>
<span class="line"><span>oc&gt; mkfs.fat32 ata0 confirm     (format - the confirm arg is required)</span></span>
<span class="line"><span>oc&gt; mkfs.exfat usda confirm</span></span>
<span class="line"><span>oc&gt; mkfs.ext4 ata0 confirm</span></span>
<span class="line"><span>oc&gt; fatmount ata0 /mnt          (mount FAT32)</span></span>
<span class="line"><span>oc&gt; mount                       (list mounts; umount unmounts)</span></span></code></pre></div><p>Formatting is destructive - every <code>mkfs.*</code> requires the literal <code>confirm</code> argument so a stray Enter does not erase a disk.</p><h2 id="the-etc-volume" tabindex="-1">The /etc volume <a class="header-anchor" href="#the-etc-volume" aria-label="Permalink to &quot;The /etc volume&quot;">​</a></h2><p>A 32 MiB FAT32 image holding the system&#39;s persistent state:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>opencube.conf     (key=value system configuration - see \`config\`)</span></span>
<span class="line"><span>ssh host keys     (sshd identity - see [network](network.md))</span></span>
<span class="line"><span>kernel.log        (rotated kernel log - see [../internals/klog.md])</span></span>
<span class="line"><span>crash dumps       (see [recovery](recovery.md))</span></span></code></pre></div><p>Configuration reads/writes go through the <code>config</code> command and the L1 <code>l1_ext_config_*</code> interface family; the /etc volume is mounted automatically at boot when present.</p><h2 id="block-devices" tabindex="-1">Block devices <a class="header-anchor" href="#block-devices" aria-label="Permalink to &quot;Block devices&quot;">​</a></h2><p>The block layer names instances (<code>ata0</code>, <code>usda</code>, <code>nvme0</code>, <code>vdisk0</code> for virtio, <code>sd0</code> for SD) and provides partition scanning on top:</p><ul><li><strong>ATA/ATAPI</strong> PIO and bus-master DMA (PRDT alignment guaranteed by the heap&#39;s 32-byte header block)</li><li><strong>AHCI</strong> - SATA controllers</li><li><strong>NVMe</strong> - PCIe SSDs</li><li><strong>virtio-blk</strong> - the fast path under QEMU (<code>-device virtio-blk-pci</code>)</li><li><strong>USB MSC</strong> - mass-storage sticks through any of the USB stacks</li><li><strong>SD/SDHCI</strong> and <strong>SCSI</strong> (LSI 53C8xx family) controllers</li></ul><h2 id="partition-tables" tabindex="-1">Partition tables <a class="header-anchor" href="#partition-tables" aria-label="Permalink to &quot;Partition tables&quot;">​</a></h2><p>GPT and MBR (msdos) partition tables are scanned; partition devices appear alongside whole-disk devices. <code>fdisk</code>-style inspection plus per-partition mount is available - see the <a href="./commands/">commands reference</a> for the disk domain.</p><h2 id="file-commands" tabindex="-1">File commands <a class="header-anchor" href="#file-commands" aria-label="Permalink to &quot;File commands&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; ls /mnt</span></span>
<span class="line"><span>oc&gt; cat /mnt/hello.txt</span></span>
<span class="line"><span>oc&gt; write /mnt/hello.txt &quot;new content&quot;</span></span>
<span class="line"><span>oc&gt; cp /mnt/a.txt /mnt/b.txt</span></span>
<span class="line"><span>oc&gt; mv /mnt/a.txt /mnt/c.txt</span></span>
<span class="line"><span>oc&gt; rm /mnt/c.txt</span></span>
<span class="line"><span>oc&gt; mkdir /mnt/dir</span></span>
<span class="line"><span>oc&gt; touch /mnt/empty.txt</span></span>
<span class="line"><span>oc&gt; editor /mnt/notes.txt        (full-screen editor)</span></span>
<span class="line"><span>oc&gt; fsck ata0                     (filesystem check)</span></span>
<span class="line"><span>oc&gt; fstest                        (VFS + per-fs self-test suite)</span></span></code></pre></div><h2 id="limits-worth-knowing" tabindex="-1">Limits worth knowing <a class="header-anchor" href="#limits-worth-knowing" aria-label="Permalink to &quot;Limits worth knowing&quot;">​</a></h2><ul><li>Long paths and file names: FAT32 LFN is fully supported including alias generation with collision scanning and checksum/sequence validation on read.</li><li>Dual-FAT mirror maintenance and FSINFO free-cluster hints are maintained on FAT32; exFAT tracks the active FAT.</li><li>ramfs sparse holes read back as zeros.</li><li><code>umount /</code> is refused; mount shadowing does not duplicate children.</li></ul>`,20)])])}const u=t(o,[["render",i]]);export{h as __pageData,u as default};
